package com.consense.service.advice;

import com.consense.ai.*;
import com.consense.common.JsonUtils;
import com.consense.config.ConsenseProperties;
import com.consense.service.vetting.VettingCorpus;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Synthetic complete-wire/gate tests. Provider/quality results are never claimed. */
class AdviceResponsesTransportTest {
    static final String SOURCE=VettingCorpus.hash("owned-current-source"),SECRET="synthetic-secret-not-a-real-key";
    static class Answer {public boolean grounded;public String answer;}
    static String output(String text){return "{\"object\":\"response\",\"model\":\"MiniMax-M3\",\"status\":\"completed\",\"truncation\":\"disabled\",\"output\":[{\"type\":\"message\",\"role\":\"assistant\",\"status\":\"completed\",\"content\":[{\"type\":\"output_text\",\"text\":"+JsonUtils.write(text)+"}]}]}";}
    static String count(long tokens){return "{\"object\":\"response.input_tokens\",\"input_tokens\":"+tokens+"}";}
    static class Http implements AdviceResponsesTransport.WireHttp {
        final List<String> endpoints=new ArrayList<>(),bodies=new ArrayList<>();final Deque<AdviceResponsesTransport.Response> replies=new ArrayDeque<>();Runnable sideEffect;
        public AdviceResponsesTransport.Response post(String endpoint,String body,long timeout,int cap,String auth){assertEquals("Bearer "+SECRET,auth);endpoints.add(endpoint);bodies.add(body);if(sideEffect!=null)sideEffect.run();return replies.removeFirst();}
        void counter(long tokens){replies.add(new AdviceResponsesTransport.Response(200,count(tokens)));}
        void generation(String text){replies.add(new AdviceResponsesTransport.Response(200,output(text)));}
    }
    static class Fixture {
        final ConsenseProperties props=new ConsenseProperties();final AdviceModelProperties settings=new AdviceModelProperties();final Http http=new Http();
        final LlmProfiles profiles;final LlmOperation selection;final AdviceResponsesTransport transport;
        Fixture(){props.getMinimaxCn().setApiKey(SECRET);props.getMinimaxCn().setStructuredOpenAiThinkingMode("disabled");settings.setMinimaxWire("responses");
            ConsenseProperties.Responses c=settings.getResponses();c.setEnabled(true);c.setConfiguredContextTokens(32768);c.setSafetyMarginTokens(1024);c.setEstimatePolicy(AdviceResponsesTransport.POLICY);
            profiles=new LlmProfiles(props,mock(LlmClient.class),mock(LlmClient.class));selection=profiles.resolve("minimax-cn");transport=new AdviceResponsesTransport(props,settings,http);}
        AdviceResponsesTransport.Operation operation(){return transport.capture(selection);}
    }
    @Test void wholeSystemQuestionBackgroundAndCodecArePreservedInExactCounterProjectionAndGeneration(){
        Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();String system="System: legal scope",user="Question:完整原题\nMaterial:{\"metadataValues\":[\"q\\\"\\n\"],\"source\":[\"entire table\"]}\nBackground: full assumptions";
        AdviceResponsesTransport.PreparedRequest request=op.prepare(system,user,SOURCE,0);JsonNode body=JsonUtils.parse(request.getGenerationJson()),counter=JsonUtils.parse(request.getCounterJson());
        assertEquals(system+AdviceResponsesTransport.JSON_INSTRUCTION,body.path("instructions").asText());assertEquals(user,body.path("input").get(0).path("content").asText());
        assertEquals(16384,body.path("max_output_tokens").asInt());assertEquals("none",body.path("reasoning").path("effort").asText());assertFalse(body.has("response_format"));assertFalse(body.has("text"));assertFalse(body.has("n"));assertFalse(body.has("store"));assertFalse(body.has("truncation"));
        assertEquals(4,counter.size());for(String key:Arrays.asList("model","instructions","input","reasoning"))assertEquals(body.get(key),counter.get(key));
        f.http.counter(1000);f.http.generation("{\"grounded\":true,\"answer\":\"complete\"}");AdviceResponsesTransport.BudgetResult result=op.observe(request,()->{});
        assertEquals("provider_estimated_fit",result.getStatus());assertEquals(AdviceResponsesTransport.KIND,result.getKind());assertFalse(result.isExactTemplateObserved());
        assertEquals("{\"grounded\":true,\"answer\":\"complete\"}",op.generate(request,result,()->{}));
        assertEquals(Arrays.asList("https://api.minimax.cn/v1/responses/input_tokens","https://api.minimax.cn/v1/responses"),f.http.endpoints);assertEquals(request.getCounterJson(),f.http.bodies.get(0));assertEquals(request.getGenerationJson(),f.http.bodies.get(1));
        assertFalse(request.getGenerationJson().contains(SECRET));assertFalse(JsonUtils.write(op.getIdentity()).contains(SECRET));
    }
    @Test void unknownPolicyIsExplicitAndSendsNeitherCounterNorGeneration(){Fixture f=new Fixture();f.settings.getResponses().setConfiguredContextTokens(0);AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","u",SOURCE,0);AdviceResponsesTransport.BudgetResult budget=op.observe(r,()->{});assertEquals("budget_unknown",budget.getStatus());assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(r,budget,()->{}));assertTrue(f.http.bodies.isEmpty());}
    @Test void operationLimitAbovePublishedM3ContextCannotEstablishAdmission(){Fixture f=new Fixture();f.settings.getResponses().setConfiguredContextTokens(AdviceResponsesTransport.PUBLIC_M3_CONTEXT_BOUND+1);AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","whole material",SOURCE,0);AdviceResponsesTransport.BudgetResult budget=op.observe(r,()->{});assertEquals("budget_unknown",budget.getStatus());assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(r,budget,()->{}));assertTrue(f.http.bodies.isEmpty());}
    @Test void declaredPublishedContextBoundIsStillOnlyAnEstimatePolicy(){Fixture f=new Fixture();f.settings.getResponses().setConfiguredContextTokens(AdviceResponsesTransport.PUBLIC_M3_CONTEXT_BOUND);AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","whole material",SOURCE,0);f.http.counter(AdviceResponsesTransport.PUBLIC_M3_CONTEXT_BOUND-16384-1024);AdviceResponsesTransport.BudgetResult budget=op.observe(r,()->{});assertEquals("provider_estimated_fit",budget.getStatus());assertEquals(AdviceResponsesTransport.KIND,budget.getKind());assertFalse(budget.isExactTemplateObserved());assertEquals(1,f.http.bodies.size());}
    @Test void outputReserveAndMarginCanRejectWithoutTruncatingOriginalMaterial(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();String user=String.join("",Collections.nCopies(20000,"完整正文\\n "));AdviceResponsesTransport.PreparedRequest r=op.prepare("s",user,SOURCE,0);f.http.counter(15361);AdviceResponsesTransport.BudgetResult budget=op.observe(r,()->{});assertEquals("over_budget",budget.getStatus());assertEquals(user,JsonUtils.parse(r.getGenerationJson()).path("input").get(0).path("content").asText());assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(r,budget,()->{}));assertEquals(1,f.http.bodies.size());}
    @Test void boundReceiptCannotBeReusedForChangedQuestionSourceOrAnotherOperation(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","u",SOURCE,0);f.http.counter(1000);AdviceResponsesTransport.BudgetResult b=op.observe(r,()->{});assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(op.prepare("s","changed",SOURCE,0),b,()->{}));assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(op.prepare("s","u",VettingCorpus.hash("changed source"),0),b,()->{}));assertThrows(AdviceResponsesTransport.RequestFailure.class,()->f.operation().generate(r,b,()->{}));assertEquals(1,f.http.bodies.size());}
    @Test void configurationOrMarginChangeInvalidatesTheFrozenOperation(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","u",SOURCE,0);f.http.counter(1000);AdviceResponsesTransport.BudgetResult b=op.observe(r,()->{});f.settings.getResponses().setSafetyMarginTokens(1025);assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(r,b,()->{}));assertEquals(1,f.http.bodies.size());}
    @Test void sourceChangesDuringCounterRejectAndNeverGenerate(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","u",SOURCE,0);f.http.counter(1000);AtomicInteger guards=new AtomicInteger();assertThrows(IllegalStateException.class,()->op.observe(r,()->{if(guards.incrementAndGet()==2)throw new IllegalStateException("owned changed source");}));assertEquals(1,f.http.bodies.size());}
    @Test void sourceGuardRequiredForBothPhases(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.PreparedRequest r=op.prepare("s","u",SOURCE,0);assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.observe(r,null));f.http.counter(1000);AdviceResponsesTransport.BudgetResult b=op.observe(r,()->{});assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.generate(r,b,null));assertEquals(1,f.http.bodies.size());}
    @Test void malformedJsonRetryHasNewFullWireAndFreshCountBeforeItsGeneration(){Fixture f=new Fixture();AdviceResponsesTransport.Operation op=f.operation();f.http.counter(1000);f.http.generation("not json");f.http.counter(1004);f.http.generation("{\"grounded\":true,\"answer\":\"fixed JSON\"}");AdviceResponsesTransport.Completion<Answer> answer=op.completeJson("s","complete material and question",SOURCE,Answer.class,()->{});assertTrue(answer.value.grounded);assertEquals(2,answer.budgets.size());assertNotEquals(answer.budgets.get(0).getBindingSha256(),answer.budgets.get(1).getBindingSha256());assertEquals(4,f.http.bodies.size());JsonNode first=JsonUtils.parse(f.http.bodies.get(1)),retry=JsonUtils.parse(f.http.bodies.get(3));assertEquals(first.path("instructions"),retry.path("instructions"));assertEquals(first.path("input").get(0).path("content").asText()+AdviceResponsesTransport.RETRY_INSTRUCTION,retry.path("input").get(0).path("content").asText());}
    @Test void retryOverBudgetStopsAfterSecondCounterAndDoesNotRegenerate(){Fixture f=new Fixture();f.http.counter(15360);f.http.generation("not json");f.http.counter(15361);AdviceResponsesTransport.RequestFailure error=assertThrows(AdviceResponsesTransport.RequestFailure.class,()->f.operation().completeJson("s","complete material",SOURCE,Answer.class,()->{}));assertEquals("over_budget",error.getStatus());assertEquals(3,f.http.bodies.size());}
    @Test void duplicateCounterUnknownFieldBooleanAndWrongModelAreRejected(){for(String bad:Arrays.asList("{\"object\":\"response.input_tokens\",\"input_tokens\":1,\"input_tokens\":2}","{\"object\":\"response.input_tokens\",\"input_tokens\":true}","{\"object\":\"response.input_tokens\",\"input_tokens\":1,\"model\":\"other\"}","{\"object\":\"response.input_tokens\",\"input_tokens\":1,\"extra\":0}")){Fixture f=new Fixture();f.http.replies.add(new AdviceResponsesTransport.Response(200,bad));AdviceResponsesTransport.Operation op=f.operation();assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.observe(op.prepare("s","u",SOURCE,0),()->{}));assertEquals(1,f.http.bodies.size());}}
    @Test void counterHttpErrorsRemainSafeAndNoProviderErrorBodyIsRetained(){Fixture f=new Fixture();f.http.replies.add(new AdviceResponsesTransport.Response(529,"credential "+SECRET));AdviceResponsesTransport.Operation op=f.operation();AdviceResponsesTransport.RequestFailure e=assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.observe(op.prepare("s","u",SOURCE,0),()->{}));assertEquals(Integer.valueOf(529),e.getHttpStatus());assertFalse(e.getMessage().contains(SECRET));assertEquals(1,f.http.bodies.size());}
    @Test void generationTruncationRefusalToolsAndWrongIdentityAreNotRetriedOrParsedAsAnswer(){for(String bad:Arrays.asList(output("{} ").replace("\"status\":\"completed\"","\"status\":\"incomplete\""),output("{}").replace("MiniMax-M3","other"),output("{}").replace("output_text","refusal"),output("{}").replace("\"type\":\"message\"","\"type\":\"function_call\""))){Fixture f=new Fixture();f.http.counter(1000);f.http.replies.add(new AdviceResponsesTransport.Response(200,bad));assertThrows(AdviceResponsesTransport.RequestFailure.class,()->f.operation().completeJson("s","u",SOURCE,Answer.class,()->{}));assertEquals(2,f.http.bodies.size());}}
    @Test void responseCapAndUnknownRouteRemainExplicitFailures(){Fixture f=new Fixture();f.settings.setMinimaxWire("invalid");assertThrows(AdviceResponsesTransport.RequestFailure.class,()->f.transport.selected(f.selection));f.settings.setMinimaxWire("responses");f.http.replies.add(new AdviceResponsesTransport.Response(200,String.join("",Collections.nCopies(1100000,"x"))));AdviceResponsesTransport.Operation op=f.operation();assertThrows(AdviceResponsesTransport.RequestFailure.class,()->op.observe(op.prepare("s","u",SOURCE,0),()->{}));}
    @Test void defaultChatAndLocalSelectionRemainUnchanged(){Fixture f=new Fixture();f.settings.setMinimaxWire("chat");assertFalse(f.transport.selected(f.selection));f.settings.setMinimaxWire("responses");assertFalse(f.transport.selected(f.profiles.resolve("local")));assertFalse(f.transport.selected(null));}
    @Test void automaticOrUnknownTruncationNeverBecomesAnAcceptedAnswer(){for(String bad:Arrays.asList(output("{}").replace("\"truncation\":\"disabled\"","\"truncation\":\"auto\""),output("{}").replace("\"truncation\":\"disabled\",",""))){Fixture f=new Fixture();f.http.counter(1000);f.http.replies.add(new AdviceResponsesTransport.Response(200,bad));AdviceResponsesTransport.RequestFailure error=assertThrows(AdviceResponsesTransport.RequestFailure.class,()->f.operation().completeJson("s","whole material",SOURCE,Answer.class,()->{}));assertEquals("generation_input_truncation_not_verified",error.getReason());assertEquals(2,f.http.bodies.size());}}
    @Test void secretRotationDoesNotEnterIdentityOrChangeTheFrozenWire(){Fixture f=new Fixture();AdviceResponsesTransport.Operation first=f.operation();String before=JsonUtils.write(first.getIdentity());f.props.getMinimaxCn().setApiKey("new-synthetic-key");AdviceResponsesTransport.Operation second=f.operation();assertEquals(before,JsonUtils.write(second.getIdentity()));assertEquals(first.prepare("s","u",SOURCE,0).getGenerationJson(),second.prepare("s","u",SOURCE,0).getGenerationJson());}
}
